'use strict';
(()=>{
 const root=document.querySelector('#admin-root'),status=document.querySelector('#admin-status');let state,tab='catalog';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const kinds={animal:'Animal',crossing:'Cruzamento',article:'Notícia',page:'Institucional'},cats={esporte:'PB Esporte',matriz:'PB Matriz',futuras:'PB Futuras',potros:'Potros',congelados:'Embriões congelados',gestacoes:'Gestações futuras'};
 const sex=s=>s==='Fêmea'?'female':s==='Macho'?'male':'unknown';
 async function api(path,data){const r=await fetch(path,data===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const out=await r.json();if(!r.ok)throw Error(out.error||'Não foi possível concluir.');return out}
 async function load(){state=await api('/api/admin');draw()}
 function tabs(){return `<div class="admin-tabs" role="group" aria-label="Áreas de gestão">${[['catalog','Catálogo e conteúdo'],['inquiries','Consultas'],...(state.user.role==='admin'?[['settings','Configurações'],['members','Equipe'],['backup','Banco de dados']]:[])].map(([id,name])=>`<button data-tab="${id}" aria-pressed="${tab===id}">${name}</button>`).join('')}</div>`}
 function draw(){root.innerHTML=tabs()+({catalog:catalog,inquiries:inquiries,settings:settings,members:members,backup:backup}[tab]());bind()}
 function catalog(){return `<div class="admin-stat-grid">${Object.entries(kinds).map(([k,v])=>`<div class="admin-stat"><strong>${state.entries.filter(x=>x.kind===k).length}</strong>${v}</div>`).join('')}</div><div class="admin-tools"><input id="admin-search" type="search" placeholder="Buscar nome, mãe, pai ou categoria" aria-label="Buscar cadastro"><button class="button" id="new-entry">Novo cadastro ＋</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Nome</th><th>Tipo / categoria</th><th>Situação / conferência</th><th>Ações</th></tr></thead><tbody>${state.entries.map(e=>`<tr data-row-search="${esc((e.title+' '+(e.info.mother||'')+' '+(e.info.father||'')+' '+e.categories.map(c=>cats[c]).join(' ')).toLowerCase())}"><td>${esc(e.title)}</td><td>${kinds[e.kind]}<br>${esc(e.categories.map(c=>cats[c]).join(' / '))}</td><td>${({published:'Publicado',draft:'Rascunho',archived:'Arquivado'})[e.status]}${e.kind==='animal'?`<br><small>${({verified:'3 gerações conferidas',partial:'Filiação parcial',legacy:'Referência Stud PB',conflict:'Divergência nas fontes',pending:'Revisão pendente'})[e.info.pedigreeVerification]||'Revisão pendente'}</small>`:''}</td><td><button data-edit="${e.id}">Editar</button>${['animal','crossing'].includes(e.kind)?`<a href="/admin/pedigree/${encodeURIComponent(e.id)}/">Pedigree</a>`:''}<a href="${publicPath(e)}" target="_blank" rel="noopener">Ver ficha ↗</a></td></tr>`).join('')}</tbody></table></div>`}
 function publicPath(e){return e.kind==='article'?'/noticias/'+e.slug+'/':e.kind==='page'?'/'+e.slug+'/':e.kind==='crossing'?'/cruzamentos/'+e.slug+'/':'/animais/'+e.slug+'/'}
 function field(label,name,value='',type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${name==='title'||name==='slug'?'required':''} maxlength="${name==='image'?2000:180}"></label>`}
 function edit(id){const original=state.entries.find(e=>e.id===id);const e=original?structuredClone(original):{id:'',title:'',slug:'',kind:'animal',body:'',image:'',gallery:[],info:{},pedigree:{name:'',sex:'unknown',mother:null,father:null},categories:[],status:'draft',version:0,source_url:'',published_at:'',updated_at:''};
 root.innerHTML=`<button id="back-panel" class="text-link">← Voltar ao catálogo</button><h2 class="admin-editor-title">${e.id?'Editar cadastro':'Novo cadastro'}</h2>${e.info.pedigreeReviewNote?`<p class="admin-note">${esc(e.info.pedigreeReviewNote)}</p>`:''}<form id="entry-form" class="system-form"><div class="admin-form-grid">${field('Nome / título','title',e.title)}${field('Endereço da ficha (sem espaços ou acentos)','slug',e.slug)}<label>Tipo<select name="kind">${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${e.kind===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Publicação<select name="status">${[['draft','Rascunho'],['published','Publicado'],['archived','Arquivado']].map(([k,v])=>`<option value="${k}" ${e.status===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="wide"><p>Categorias</p><div class="category-checks">${Object.entries(cats).map(([k,v])=>`<label><input type="checkbox" name="categories" value="${k}" ${e.categories.includes(k)?'checked':''}>${v}</label>`).join('')}</div></div>${field('Pai','father',e.info.father)}${field('Mãe','mother',e.info.mother)}${field('Ano de nascimento','year',e.info.year)}${field('Data de nascimento (DD/MM/AAAA)','birth',e.info.birth)}${field('Previsão de nascimento','forecast',e.info.forecast)}<label>Sexo<select name="sex">${['Não informado','Macho','Fêmea'].map(v=>`<option ${e.info.sex===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Disponibilidade<select name="availability"><option value="consult">Sob consulta</option><option value="sold" ${e.info.availability==='sold'?'selected':''}>Vendido</option></select></label>${field('Fotografia principal (URL HTTPS ou arquivo enviado)','image',e.image)}<div class="wide upload-row"><input id="image-file" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Selecionar fotografia"><button type="button" id="upload-image">Enviar fotografia</button><span id="upload-status" role="status"></span></div><label class="wide">Galeria (uma URL por linha)<textarea name="gallery" rows="4">${esc(e.gallery.join('\n'))}</textarea></label><label class="wide">História / texto (parágrafos separados por linha em branco)<textarea name="body" rows="12" maxlength="80000">${esc(e.body)}</textarea></label></div><div class="admin-form-actions"><button class="button" type="submit">Salvar cadastro ↗</button>${e.id&&['animal','crossing'].includes(e.kind)?`<a class="text-link" href="/admin/pedigree/${encodeURIComponent(e.id)}/">Abrir editor de pedigree →</a>`:''}<button type="button" id="cancel-edit" class="text-link">Cancelar</button></div></form>`;
 document.querySelector('#back-panel').onclick=draw;document.querySelector('#cancel-edit').onclick=draw;
 const form=document.querySelector('#entry-form');
 if(!e.id)form.elements.title.oninput=()=>form.elements.slug.value=form.elements.title.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
 document.querySelector('#upload-image').onclick=async()=>{const file=document.querySelector('#image-file').files[0],label=document.querySelector('#upload-status');if(!file){label.textContent='Selecione uma imagem.';return}const data=new FormData();data.set('file',file);try{label.textContent='Enviando…';const r=await fetch('/api/upload',{method:'POST',body:data}),out=await r.json();if(!r.ok)throw Error(out.error);form.elements.image.value=out.url;label.textContent='Imagem enviada. Salve o cadastro.'}catch(err){label.textContent=err.message}};
 form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;const f=new FormData(form);const d={...e};for(const k of ['title','slug','kind','status','body','image'])d[k]=f.get(k);d.gallery=String(f.get('gallery')).split('\n').map(x=>x.trim()).filter(Boolean);d.categories=f.getAll('categories');d.info={...e.info};for(const k of ['mother','father','year','birth','forecast','sex','availability'])d.info[k]=f.get(k);d.pedigree={...e.pedigree,name:d.title,sex:sex(d.info.sex)};for(const [k,s] of [['mother','female'],['father','male']])if(d.info[k]!==e.pedigree?.[k]?.name)d.pedigree[k]=d.info[k]?{name:d.info[k],sex:s,mother:null,father:null}:null;
 try{await api('/api/entries',d);status.textContent='Cadastro salvo no banco de dados.';await load()}catch(err){status.textContent=err.message;b.disabled=false;status.scrollIntoView({block:'center'})}};
 }
 function inquiries(){return `<h2>Consultas recebidas</h2><p class="admin-note">O formulário registra a consulta neste painel. Não há envio automático por e-mail ou WhatsApp.</p>${state.inquiries.length?state.inquiries.map(x=>`<article class="admin-message"><h3>${esc(x.name)} <small> / ${esc(x.interest)}</small></h3><p>${esc(x.created_at.slice(0,16).replace('T',' '))}<br><a href="mailto:${esc(x.email)}">${esc(x.email)}</a> ${esc(x.phone)}</p><p>${esc(x.message)}</p><div>${[['new','Nova'],['contacted','Em atendimento'],['closed','Concluída']].map(([k,v])=>`<button data-inquiry="${x.id}" data-status="${k}" aria-pressed="${x.status===k}">${v}</button>`).join('')}</div></article>`).join(''):'<p>Nenhuma consulta recebida.</p>'}`}
 function settings(){const s=state.settings;return `<h2>Configurações do site</h2><form id="settings-form" class="system-form"><input type="hidden" name="pedigree_order" value="paternal-first"><p class="admin-note">Convenção do site: pai primeiro. Nas árvores, macho acima e fêmea abaixo em todas as gerações; nos cruzamentos, Pai × Mãe. Os vínculos de parentesco mantêm seus significados.</p>${field('Saudação do cabeçalho','welcome',s.welcome)}${field('E-mail de atendimento','contact_email',s.contact_email,'email')}${field('WhatsApp oficial (DDI + DDD + número, apenas dígitos)','contact_whatsapp',s.contact_whatsapp)}${field('Endereço','address',s.address)}${field('Instagram','instagram',s.instagram)}${field('YouTube','youtube',s.youtube)}<button class="button" type="submit">Salvar configurações ↗</button></form>`}
 function members(){return `<h2>Equipe autorizada</h2><p class="admin-note">Cadastre o e-mail usado pela pessoa no ChatGPT. No primeiro acesso autorizado, a identidade é vinculada ao cadastro. Editores gerenciam conteúdo e consultas. Administradores também gerenciam equipe, configurações e exportações.</p><table class="admin-table"><thead><tr><th>E-mail</th><th>Perfil</th><th>Acesso</th></tr></thead><tbody>${state.members.map(m=>`<tr><td>${esc(m.email)}</td><td>${m.role==='admin'?'Administrador':'Editor'}</td><td><button data-member="${m.id}">${m.active?'Desativar':'Reativar'}</button></td></tr>`).join('')}</tbody></table><form id="member-form" class="system-form"><h3>Adicionar ou atualizar acesso</h3>${field('E-mail','email','','email')}<label>Perfil<select name="role"><option value="editor">Editor</option><option value="admin">Administrador</option></select></label><button class="button" type="submit">Autorizar acesso ↗</button></form>`}
 function backup(){return `<h2>Banco de dados</h2><p>Exporte o estado atual do catálogo, pedigrees, configurações, equipe e consultas.</p><a class="button" href="/api/export.sql">Baixar backup SQL ↓</a><p class="admin-note">Formato SQLite / Cloudflare D1. O arquivo inclui dados de atendimento e deve ficar restrito à equipe. As imagens enviadas ficam no armazenamento de mídia e precisam de backup separado. O pacote inicial entregue inclui as imagens importadas do site original e o relatório de migração.</p>`}
 function bind(){root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;status.textContent='';draw()});root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));root.querySelector('#new-entry')?.addEventListener('click',()=>edit(''));root.querySelector('#admin-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();root.querySelectorAll('[data-row-search]').forEach(r=>r.hidden=!r.dataset.rowSearch.includes(q))});
 root.querySelectorAll('[data-inquiry]').forEach(b=>b.onclick=async()=>{try{await api('/api/inquiry-status',{id:b.dataset.inquiry,status:b.dataset.status});await load()}catch(err){status.textContent=err.message}});
 root.querySelector('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/settings',Object.fromEntries(new FormData(e.target)));status.textContent='Configurações publicadas.';await load()}catch(err){status.textContent=err.message}});
 root.querySelector('#member-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/members',{...Object.fromEntries(new FormData(e.target)),active:1});status.textContent='Acesso autorizado.';await load()}catch(err){status.textContent=err.message}});
 root.querySelectorAll('[data-member]').forEach(b=>b.onclick=async()=>{const m=state.members.find(m=>m.id===b.dataset.member);try{await api('/api/members',{email:m.email,role:m.role,active:m.active?0:1});await load()}catch(err){status.textContent=err.message}});
 }
 load().catch(err=>{root.textContent='Não foi possível carregar o painel.';status.textContent=err.message});
})();
